    def longestPalindrome(self, s: str, t: str) -> int:
        # Check if both strings are the same
        if s == t:
            return len(s)

        # Initialize variables
        m, n = len(s), len(t)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Fill the DP table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        # The maximum value in the bottom-right corner of the DP table is the length of the longest palindrome
        return dp[m][n]
